CREATE DATABASE IF NOT EXISTS charger_caffe;
USE charger_caffe;
CREATE TABLE IF NOT EXISTS admins(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),username VARCHAR(100) UNIQUE,password VARCHAR(100));
CREATE TABLE IF NOT EXISTS customers(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),username VARCHAR(100) UNIQUE,password VARCHAR(100));
CREATE TABLE IF NOT EXISTS products(id BIGINT PRIMARY KEY,name VARCHAR(100),category VARCHAR(50),price DECIMAL(10,2),available TINYINT(1));
CREATE TABLE IF NOT EXISTS inventory(id BIGINT PRIMARY KEY,name VARCHAR(100),category VARCHAR(50),unit VARCHAR(20),stock DECIMAL(10,2),reorder DECIMAL(10,2));
CREATE TABLE IF NOT EXISTS recipes(product_id BIGINT,inventory_id BIGINT,amount DECIMAL(10,4),PRIMARY KEY(product_id,inventory_id));
CREATE TABLE IF NOT EXISTS sales(id INT AUTO_INCREMENT PRIMARY KEY,ts BIGINT,customer VARCHAR(100) NULL,status VARCHAR(20) NULL,total DECIMAL(10,2));
CREATE TABLE IF NOT EXISTS sale_items(id INT AUTO_INCREMENT PRIMARY KEY,sale_id INT,name VARCHAR(100),qty INT,price DECIMAL(10,2),INDEX(sale_id));
